package com.andye.warmod.radar.display.client;
import org.jspecify.annotations.Nullable;
public final class RadarDisplayTileClip { private RadarDisplayTileClip(){} public static @Nullable Segment line(RadarDisplayMapTransform.Point start,RadarDisplayMapTransform.Point end,int tileX,int tileY){double minX=tileX,maxX=tileX+1,minY=tileY,maxY=tileY+1,dx=end.x()-start.x(),dy=end.y()-start.y(),lower=0,upper=1;double[] p={-dx,dx,-dy,dy},q={start.x()-minX,maxX-start.x(),start.y()-minY,maxY-start.y()};for(int i=0;i<4;i++){if(Math.abs(p[i])<1E-9){if(q[i]<0)return null;continue;}double ratio=q[i]/p[i];if(p[i]<0)lower=Math.max(lower,ratio);else upper=Math.min(upper,ratio);if(lower>upper)return null;}return new Segment(new Point(start.x()+dx*lower-tileX,start.y()+dy*lower-tileY),new Point(start.x()+dx*upper-tileX,start.y()+dy*upper-tileY));} public static boolean contains(RadarDisplayMapTransform.Point point,int tileX,int tileY){return point.x()>=tileX&&point.x()<=tileX+1&&point.y()>=tileY&&point.y()<=tileY+1;} public static Point local(RadarDisplayMapTransform.Point point,int tileX,int tileY){return new Point(point.x()-tileX,point.y()-tileY);} public record Point(double x,double y){} public record Segment(Point start,Point end){} }